"use client";

import { Checkbox } from "@base-ui/react/checkbox";
import { type ComponentPropsWithoutRef, forwardRef } from "react";
import { InspectorFieldLock } from "./inspector-field-lock";
import { useInspectorField } from "./inspector-field-state";
import { cn } from "@/lib/utils";

type CheckboxProps = Omit<ComponentPropsWithoutRef<"div">, "onChange"> & {
  /** Whether it is on, or null when a selection differs. The application owns it. */
  checked: boolean | null;
  /** Called with the new state; a Mixed checkbox turns on. */
  onCommit: (checked: boolean) => void;
  /** Shortcut text shown after the label, such as "⌥C". Your app binds the key. */
  shortcut?: string;
  /** Class for the box itself. */
  boxClassName?: string;
};

/**
 * A built-in checkbox row, such as Clip content: the box first and the row's label beside it, across
 * the whole row, so it needs no InspectorFieldLabel. Mixed shows a dash; locked rows show the lock.
 */
export const InspectorFieldCheckbox = forwardRef<HTMLDivElement, CheckboxProps>(function InspectorFieldCheckbox(
  { checked, onCommit, shortcut, boxClassName, className, ...props },
  ref,
) {
  const field = useInspectorField();
  const mixed = field.mixed || checked === null;
  const blocked = !field.editable || field.pending;
  const off = field.disabled || field.locked || field.unavailable;
  return (
    <div
      ref={ref}
      data-slot="checkbox"
      className={cn(
        // It spans the label and control columns, in either label position.
        "col-span-2 col-start-1 flex h-[var(--uicoolkit-field-height,2.5rem)] min-w-0 items-center gap-2.5 [grid-area:1/1/2/3]!",
        field.inside && "px-3.5",
        off && "opacity-50",
        className,
      )}
      {...props}
    >
      <Checkbox.Root
        id={field.controlId}
        checked={!mixed && !!checked}
        indeterminate={mixed}
        disabled={off}
        readOnly={blocked}
        aria-labelledby={field.labelId}
        aria-describedby={field.describedBy}
        aria-keyshortcuts={shortcut}
        onCheckedChange={(next) => {
          if (blocked || off) return;
          onCommit(mixed ? true : next);
        }}
        className={cn(
          "grid size-4 shrink-0 place-items-center rounded-[4px] border border-input bg-transparent text-primary-foreground shadow-xs outline-none transition-colors duration-150 motion-reduce:transition-none",
          "focus-visible:ring-1 focus-visible:ring-ring data-[checked]:border-primary data-[checked]:bg-primary data-[indeterminate]:border-primary data-[indeterminate]:bg-primary",
          boxClassName,
        )}
      >
        <Checkbox.Indicator className="flex data-[unchecked]:hidden">
          <svg aria-hidden viewBox="0 0 16 16" className="size-3" fill="none" stroke="currentColor" strokeWidth={2.25} strokeLinecap="round" strokeLinejoin="round">
            {mixed ? <path d="M4 8h8" /> : <path d="m3.5 8.5 3 3 6-7" />}
          </svg>
        </Checkbox.Indicator>
      </Checkbox.Root>
      {/* Clicking the text toggles the box, as with a native label. */}
      <span
        id={field.labelId}
        className="min-w-0 truncate text-foreground select-none"
        onClick={() => {
          if (!blocked && !off) onCommit(mixed ? true : !checked);
        }}
      >
        {field.label}
      </span>
      {shortcut && <kbd className="font-sans text-muted-foreground">{shortcut}</kbd>}
      <InspectorFieldLock className="ml-auto" />
    </div>
  );
});

"use client";

import type { ReactNode } from "react";

// 16-unit icons drawn in the current text colour, sized by the control that holds them.
const icon = (children: ReactNode) => (
  <svg viewBox="0 0 16 16" aria-hidden fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
    {children}
  </svg>
);
const lines = (widths: [number, number][]) => icon(<path d={widths.map(([start, end], row) => `M${start} ${4 + row * 4}H${end}`).join("")} />);

/**
 * Icons for the built-in segments, toggle buttons and short labels: layout direction and wrap, text
 * alignment, angle and gap, and flips. Pass them as an option's or button's icon, or use your own.
 */
export const inspectorFieldIcons = {
  /** Children stack top to bottom. */
  vertical: icon(<path d="M8 2.75v10.5M4.25 9.5 8 13.25l3.75-3.75" />),
  /** Children run left to right. */
  horizontal: icon(<path d="M2.75 8h10.5M9.5 4.25 13.25 8 9.5 11.75" />),
  /** Children wrap onto new lines. */
  wrap: icon(<path d="M2.75 4.5h7.5a3 3 0 0 1 0 6H5.5M7.5 8.5l-2 2 2 2" />),
  alignLeft: lines([
    [2.75, 13.25],
    [2.75, 9.5],
    [2.75, 11.5],
  ]),
  alignCenter: lines([
    [2.75, 13.25],
    [5, 11],
    [4, 12],
  ]),
  alignRight: lines([
    [2.75, 13.25],
    [6.5, 13.25],
    [4.5, 13.25],
  ]),
  justify: lines([
    [2.75, 13.25],
    [2.75, 13.25],
    [2.75, 13.25],
  ]),
  /** An angle, such as Rotation's short label. */
  angle: icon(<path d="M12.75 12.5H3.25L10.5 3.5M7.25 7.75a5 5 0 0 1 1.5 4.75" />),
  /** The space between children, such as Gap's short label. */
  gap: icon(<path d="M2.75 3v10M13.25 3v10M4.75 8h6.5M6.5 6.25 4.75 8l1.75 1.75M9.5 6.25 11.25 8 9.5 9.75" />),
  /** Turn a quarter turn clockwise. */
  rotate: icon(<path d="M3.5 6.5a5 5 0 0 1 8.6-2.1M12.5 2.5v2.25h-2.25M6.5 8.5h5v5h-5z" />),
  /** Keep width and height in proportion. */
  link: icon(<path d="M6.75 9.25 9.25 6.75M7 4.5l1-1a2.47 2.47 0 0 1 3.5 3.5l-1 1M9 11.5l-1 1a2.47 2.47 0 0 1-3.5-3.5l1-1" />),
  /** Mirror left to right. */
  flipHorizontal: icon(<path d="M8 2.5v11M6 4.5 2.75 11.5H6zM10 4.5l3.25 7H10z" />),
  /** Mirror top to bottom. */
  flipVertical: icon(<path d="M2.5 8h11M4.5 6l7-3.25V6zM4.5 10l7 3.25V10z" />),
  /** How see-through a layer is, such as Opacity's short label. */
  opacity: icon(<path d="M8 2.75a5.25 5.25 0 1 1 0 10.5 5.25 5.25 0 0 1 0-10.5ZM8 2.75v10.5M8 5.5h4.25M8 8h5.25M8 10.5h4.25" />),
  /** A border drawn inside the layer's edge. */
  borderInside: icon(<path d="M5.5 2.75v10.5M5.5 2.75h7.75M5.5 13.25h7.75M8 5.5v5" />),
  /** A border centred on the layer's edge. */
  borderCenter: icon(<path d="M8 2.75v10.5M8 2.75h5.25M8 13.25h5.25M5.5 5.5v5M10.5 5.5v5" />),
  /** A border drawn outside the layer's edge. */
  borderOutside: icon(<path d="M10.5 2.75v10.5M10.5 2.75h2.75M10.5 13.25h2.75M8 5.5v5" />),
  /** A solid line. */
  solid: icon(<path d="M2.75 8h10.5" />),
  /** A dashed line. */
  dashed: icon(<path d="M2.75 8h2.5M6.75 8h2.5M10.75 8h2.5" />),
  /** Text sits at the top of its box. */
  alignTop: icon(<path d="M2.75 2.75h10.5M8 13.25V5.5M5.5 8 8 5.5 10.5 8" />),
  /** Text sits in the middle of its box. */
  alignMiddle: icon(<path d="M2.75 8h10.5M8 2.75v2.5M8 10.75v2.5M6.25 3.5 8 5.25 9.75 3.5M6.25 12.5 8 10.75l1.75 1.75" />),
  /** Text sits at the bottom of its box. */
  alignBottom: icon(<path d="M2.75 13.25h10.5M8 2.75v7.75M5.5 8 8 10.5 10.5 8" />),
  /** Font size, such as Size's short label: a large and a small T. */
  fontSize: icon(<path d="M2.75 4h6.5M6 4v9M9.75 8h3.5M11.5 8v5" />),
  /** The height of a line of text. */
  lineHeight: icon(<path d="M2.75 2.75h10.5M2.75 13.25h10.5M5.5 11 8 5l2.5 6M6.4 9h3.2" />),
  /** The space between letters. */
  letterSpacing: icon(<path d="M2.75 3v10M13.25 3v10M5.5 11 8 5l2.5 6M6.4 9h3.2" />),
  /** More settings, such as a shadow's offset and blur. */
  settings: icon(<path d="M2.75 5h10.5M2.75 11h10.5M6 3.25v3.5M10 9.25v3.5" />),
};

"use client";

import { type ComponentPropsWithoutRef, forwardRef } from "react";
import { useInspectorField } from "./inspector-field-state";
import { cn } from "@/lib/utils";

/**
 * A lock inside a control while the property is locked; nothing otherwise. Built-in controls place
 * it themselves (after a text or select value, on the toggle's selected segment). In a hosted
 * control, show it in place of its adjust buttons, such as a Number Field's stepper.
 */
export const InspectorFieldLock = forwardRef<HTMLSpanElement, ComponentPropsWithoutRef<"span">>(function InspectorFieldLock(
  { className, children, ...props },
  ref,
) {
  const field = useInspectorField();
  if (!field.locked) return null;
  return (
    <span
      ref={ref}
      role="img"
      data-slot="lock"
      aria-label={field.messages.locked}
      title={field.reason}
      className={cn("inline-flex size-4 shrink-0 items-center justify-center self-center text-muted-foreground", className)}
      {...props}
    >
      {children ?? (
        <svg aria-hidden viewBox="0 0 16 16" className="size-3.5" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
          <rect x="3.5" y="7" width="9" height="6.5" rx="1.5" />
          <path d="M5.5 7V5a2.5 2.5 0 0 1 5 0v2" />
        </svg>
      )}
    </span>
  );
});

"use client";

import { type ComponentPropsWithoutRef, type ReactNode, forwardRef } from "react";
import { InspectorFieldLock } from "./inspector-field-lock";
import { box, useInspectorField } from "./inspector-field-state";
import { cn } from "@/lib/utils";

/** The property name, in the first column. Clicking it focuses a built-in control (data-slot="label"). */
export const InspectorFieldLabel = forwardRef<HTMLLabelElement, ComponentPropsWithoutRef<"label">>(function InspectorFieldLabel(
  { className, children, ...props },
  ref,
) {
  const { label, labelId, controlId } = useInspectorField();
  return (
    <label
      ref={ref}
      id={labelId}
      htmlFor={controlId}
      data-slot="label"
      className={cn("truncate text-xs text-muted-foreground select-none group-data-unavailable/inspector:opacity-60", className)}
      {...props}
    >
      {children ?? label}
    </label>
  );
});

/**
 * A read-only value. Shows the mixed placeholder, or a dash when there is no single value.
 * While unavailable it reads as a disabled field.
 */
export const InspectorFieldValue = forwardRef<HTMLSpanElement, ComponentPropsWithoutRef<"span">>(function InspectorFieldValue(
  { className, children, ...props },
  ref,
) {
  const { mixed, unavailable, messages, align, inside, controlId, labelId, describedBy } = useInspectorField();
  return (
    <span
      ref={ref}
      id={controlId}
      aria-labelledby={labelId}
      aria-describedby={describedBy}
      aria-disabled={unavailable || undefined}
      data-unavailable={unavailable || undefined}
      className={cn(
        // Same 40px height as the editable controls, so rows line up.
        "flex h-[var(--uicoolkit-field-height,2.5rem)] min-w-0 items-center gap-1 truncate px-3 tabular-nums",
        align === "start" ? "justify-start text-start [&>[data-slot=lock]]:ml-auto" : "justify-end text-end",
        (mixed || unavailable) && "text-muted-foreground",
        // An unavailable property looks like a disabled field; the row draws the box when the label is inside.
        unavailable && (inside ? "cursor-not-allowed" : cn(box, "cursor-not-allowed opacity-50")),
        inside && "pr-3.5",
        className,
      )}
      {...props}
    >
      {unavailable ? (
        <>
          <span aria-hidden>—</span>
          <span className="sr-only">{messages.unavailable}</span>
        </>
      ) : mixed ? (
        messages.mixed
      ) : (
        children
      )}
      <InspectorFieldLock className="self-center" />
    </span>
  );
});

/** A unit after a read-only value, such as "px". */
export const InspectorFieldUnit = forwardRef<HTMLSpanElement, ComponentPropsWithoutRef<"span">>(function InspectorFieldUnit({ className, ...props }, ref) {
  return <span ref={ref} className={cn("text-xs opacity-60", className)} {...props} />;
});

/**
 * What a custom control needs from the field. Spread `props` onto it and give `describedBy` to its
 * input; while `locked`, show InspectorFieldLock in place of its own adjust buttons.
 */
export type InspectorFieldControlState = {
  props: { label: string; disabled: boolean; readOnly: boolean; placeholder?: string };
  describedBy: string | undefined;
  locked: boolean;
  /** Apply to the hosted control's value, for example `text-start` on a NumberFieldInput. */
  align: "start" | "end";
};

type ControlProps = {
  /** Renders another control, such as a NumberField, with the field's state applied. */
  children: (control: InspectorFieldControlState) => ReactNode;
  /** Shown instead while the property is unavailable. Defaults to the label and a dash. */
  unavailableFallback?: ReactNode;
};

/**
 * A slot for another control. It renders no element of its own, so a control with
 * `className="contents"` can place its own label in the first column (for example a
 * NumberFieldScrubArea, so dragging the label adjusts the value).
 */
export function InspectorFieldControl({ children, unavailableFallback }: ControlProps) {
  const field = useInspectorField();
  if (field.unavailable)
    return (
      unavailableFallback ?? (
        <>
          <InspectorFieldLabel />
          <InspectorFieldValue />
        </>
      )
    );
  return children({
    props: {
      label: field.label,
      disabled: field.disabled || field.locked,
      readOnly: field.readOnly || field.pending,
      placeholder: field.mixed ? field.messages.mixed : undefined,
    },
    describedBy: field.describedBy,
    locked: field.locked,
    align: field.align,
  });
}

/** Rejected values first, then why the field is locked or unavailable, then the hint. */
export const InspectorFieldMessage = forwardRef<HTMLParagraphElement, ComponentPropsWithoutRef<"p">>(function InspectorFieldMessage(
  { className, children, ...props },
  ref,
) {
  const { error, reason, hint, locked, unavailable, messageId, animated } = useInspectorField();
  const content = error ?? ((locked || unavailable) && reason ? reason : (children ?? hint));
  if (!content) return null;
  // A locked or unavailable property's reason shows on hover instead, but stays the field's description.
  const hoverOnly = !error && (locked || unavailable) && !!reason;
  return (
    <p
      ref={ref}
      id={messageId}
      data-slot="message"
      role={error ? "alert" : undefined}
      className={cn("px-2 text-xs text-muted-foreground", hoverOnly && "sr-only", error && "text-destructive", animated && error && "transition-opacity duration-150 starting:opacity-0 motion-reduce:transition-none", className)}
      {...props}
    >
      {content}
    </p>
  );
});

"use client";

import { Tooltip } from "@base-ui/react/tooltip";
import { cloneElement, forwardRef, useId, useRef, useState } from "react";
import { type InspectorFieldContextValue, type InspectorFieldProps, InspectorFieldContext, defaultMessages, mergeRefs } from "./inspector-field-state";
import { cn } from "@/lib/utils";

/**
 * One property row: the label and the control (with a lock inside it when locked), with an optional
 * message below. Columns line up across rows; set `--inspector-label-width` to change the label column.
 * Why a property is locked or unavailable shows in a tooltip while the row is hovered.
 */
export const InspectorField = forwardRef<HTMLDivElement, InspectorFieldProps>(function InspectorField(
  {
    label,
    mixed = false,
    readOnly = false,
    locked = false,
    unavailable = false,
    reason,
    disabled = false,
    pending = false,
    hint,
    motion = true,
    align = "end",
    labelPosition = "outside",
    messages: messagesProp,
    tooltipClassName,
    className,
    children,
    ...props
  },
  ref,
) {
  const [error, setError] = useState<string | null>(null);
  const rootRef = useRef<HTMLDivElement | null>(null);
  const id = useId();
  const messages = { ...defaultMessages, ...messagesProp };
  const editable = !readOnly && !locked && !unavailable && !disabled;
  const showsReason = (locked || unavailable) && !!reason;
  // Locked and unavailable reasons show on hover rather than taking space below the row.
  const hoverReason = showsReason;
  const hasMessage = !!error || showsReason || !!hint;

  const context: InspectorFieldContextValue = {
    label,
    mixed,
    readOnly,
    locked,
    unavailable,
    disabled,
    pending,
    editable,
    reason,
    hint,
    animated: motion,
    align,
    inside: labelPosition === "inside",
    messages,
    error,
    setError,
    describedBy: hasMessage ? `${id}-message` : undefined,
    labelId: `${id}-label`,
    controlId: `${id}-control`,
    messageId: `${id}-message`,
    rootRef,
  };

  const row = (
      <div
        ref={mergeRefs(ref, rootRef)}
        data-align={align}
        data-label-position={labelPosition}
        data-mixed={mixed || undefined}
        data-readonly={readOnly || undefined}
        data-locked={locked || undefined}
        data-unavailable={unavailable || undefined}
        data-disabled={disabled || undefined}
        data-pending={pending || undefined}
        data-invalid={error ? true : undefined}
        // With the label inside, the row is the field's box: hosted menus open under all of it.
        data-menu-anchor={labelPosition === "inside" || undefined}
        aria-busy={pending || undefined}
        className={cn(
          // Two columns: label and control, with messages under the control.
          // Parts find their place by data-slot: direct children, or one level down inside a hosted
          // control that uses className="contents" (its scrub area or error).
          "group/inspector grid grid-cols-[var(--inspector-label-width,6rem)_minmax(0,1fr)] items-center gap-x-2 text-sm [grid-template-areas:'label_control'_'._error'_'._message']",
          "[&>[data-slot=label]]:[grid-area:label] [&>*>[data-slot=scrub]]:[grid-area:label]",
          // A hosted Number Field slider takes the control column at the row's height.
          "[&>*>[data-slot=slider]]:h-[var(--uicoolkit-field-height,2.5rem)] [&>*>[data-slot=slider]]:[grid-area:control]",
          "[&>*>[data-slot=error]]:mt-1 [&>*>[data-slot=error]]:[grid-area:error] [&>[data-slot=message]]:mt-1 [&>[data-slot=message]]:[grid-area:message]",
          labelPosition === "inside" && [
            // One box around the whole first row, drawn behind the label and control. Messages sit below it.
            "isolate grid-cols-[auto_minmax(0,1fr)] gap-x-0 [grid-template-areas:'label_control'_'error_error'_'message_message']",
            "before:-z-10 before:h-[var(--uicoolkit-field-height,2.5rem)] before:rounded-md before:border before:border-[color:var(--uicoolkit-field-border,var(--input))] before:bg-[var(--uicoolkit-field-bg,transparent)] before:shadow-[var(--uicoolkit-field-shadow,0_1px_2px_0_rgb(0_0_0/0.05))] before:[grid-area:1/1/2/3]",
            "has-focus-visible:before:border-ring has-data-[popup-open]:before:border-ring",
            "has-[[aria-invalid=true]]:before:border-destructive data-disabled:before:opacity-50 data-unavailable:before:opacity-50",
            // The box fills the first row, so controls are placed explicitly instead of auto-placed after it.
            "[&>:not([data-slot=label],[data-slot=message])]:[grid-area:control] [&>*>[data-slot=group]]:[grid-area:control]",
            "[&>[data-slot=label]]:pr-2 [&>[data-slot=label]]:pl-3.5 [&>*>[data-slot=scrub]]:h-[var(--uicoolkit-field-height,2.5rem)] [&>*>[data-slot=scrub]]:pr-2 [&>*>[data-slot=scrub]]:pl-3.5",
            // A hosted control's own box gives way to the row's.
            "[&>*>[data-slot=group]]:border-transparent! [&>*>[data-slot=group]]:bg-transparent! [&>*>[data-slot=group]]:shadow-none! [&>*>[data-slot=group]]:ring-0!",
            // A slider is already a box with its label inside, so it becomes the whole row.
            "has-[>*>[data-slot=slider]]:before:hidden [&>*>[data-slot=slider]]:[grid-area:1/1/2/3]",
          ],
          className,
        )}
        {...props}
      />
  );
  return (
    <InspectorFieldContext.Provider value={context}>
      {hoverReason ? (
        <Tooltip.Root>
          <Tooltip.Trigger render={row}>{children}</Tooltip.Trigger>
          <Tooltip.Portal container={rootRef}>
            <Tooltip.Positioner side="top" align="end" sideOffset={6} positionMethod="fixed" className="z-50">
              <Tooltip.Popup
                className={cn(
                  "max-w-60 rounded-md bg-foreground px-2 py-1 text-xs text-background shadow-md",
                  motion &&
                    "origin-[var(--transform-origin)] transition-[transform,opacity] duration-150 data-[ending-style]:scale-95 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[starting-style]:opacity-0 motion-reduce:transition-none",
                  tooltipClassName,
                )}
              >
                {reason}
              </Tooltip.Popup>
            </Tooltip.Positioner>
          </Tooltip.Portal>
        </Tooltip.Root>
      ) : (
        cloneElement(row, undefined, children)
      )}
    </InspectorFieldContext.Provider>
  );
});

"use client";

import { Tooltip } from "@base-ui/react/tooltip";
import { type ComponentPropsWithoutRef, type KeyboardEvent, type PointerEvent, type ReactElement, type ReactNode, forwardRef, useEffect, useRef, useState } from "react";
import { InspectorFieldLock } from "./inspector-field-lock";
import { InspectorFieldValue } from "./inspector-field-parts";
import { mergeRefs, useInspectorField } from "./inspector-field-state";
import { cn } from "@/lib/utils";

/** One choice. With an icon, the segment shows only the icon and the label names it and fills its tooltip. */
export type InspectorFieldSegment<V extends string | boolean = string> = { value: V; label: string; icon?: ReactNode };

type TipProps = { label: string; children: ReactElement };

/** A tooltip naming an icon-only control, portalled into the row so it keeps the row's theme. */
function Tip({ label, children }: TipProps) {
  const field = useInspectorField();
  return (
    <Tooltip.Root>
      <Tooltip.Trigger render={children} />
      <Tooltip.Portal container={field.rootRef}>
        <Tooltip.Positioner side="top" sideOffset={6} positionMethod="fixed" className="z-50">
          <Tooltip.Popup
            className={cn(
              "rounded-md bg-foreground px-2 py-1 text-xs whitespace-nowrap text-background shadow-md",
              field.animated &&
                "origin-[var(--transform-origin)] transition-[transform,opacity] duration-150 data-[ending-style]:scale-95 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[starting-style]:opacity-0 motion-reduce:transition-none",
            )}
          >
            {label}
          </Tooltip.Popup>
        </Tooltip.Positioner>
      </Tooltip.Portal>
    </Tooltip.Root>
  );
}

type HoverBox = { x: number; width: number; shown: boolean; instant: boolean };

/**
 * One hover box shared by a group's items, sliding to whichever item is under the pointer. It appears
 * in place (no slide in from the edge) and fades out when the pointer leaves or rests on a skipped item.
 */
function useSharedHover(skip: (item: HTMLElement) => boolean, animated: boolean, className?: string) {
  const [box, setBox] = useState<HoverBox>({ x: 0, width: 0, shown: false, instant: true });
  const hide = () => setBox((current) => (current.shown ? { ...current, shown: false } : current));
  const handlers = {
    onPointerMove: (event: PointerEvent<HTMLDivElement>) => {
      if (event.pointerType === "touch") return;
      const item = (event.target as HTMLElement).closest<HTMLButtonElement>("button");
      if (!item || !event.currentTarget.contains(item) || item.disabled || skip(item)) return hide();
      const x = item.offsetLeft;
      const width = item.offsetWidth;
      setBox((current) => (current.shown && current.x === x && current.width === width ? current : { x, width, shown: true, instant: !current.shown }));
    },
    onPointerLeave: hide,
  };
  const highlight = (
    <span
      aria-hidden
      data-slot="hover"
      className={cn(
        "pointer-events-none absolute inset-y-0.5 left-0 -z-20 rounded-md bg-foreground/10",
        animated && "transition-opacity duration-150 motion-reduce:transition-none",
        animated && !box.instant && "transition-[transform,width,opacity] ease-out",
        className,
      )}
      style={{ width: box.width, transform: `translateX(${box.x}px)`, opacity: box.shown ? 1 : 0 }}
    />
  );
  return { handlers, highlight };
}

type SegmentsProps<V extends string | boolean> = Omit<ComponentPropsWithoutRef<"div">, "onChange"> & {
  /** The committed choice, or null when a selection differs. The application owns it. */
  value: V | null;
  /** Two to five choices. */
  options: InspectorFieldSegment<V>[];
  /** Called when a different choice is made. */
  onCommit: (value: V) => void;
  /** Class for the highlight that slides to the chosen segment. */
  highlightClassName?: string;
  /** Class for each segment. The chosen one has data-selected. */
  segmentClassName?: string;
  /** Class for the hover box that slides between unchosen segments. */
  hoverClassName?: string;
};

/**
 * A built-in segmented choice with a highlight that slides to the chosen segment. Text segments stay
 * compact at the row's end; icon segments fill the control column in equal widths and name
 * themselves in a tooltip. It is a radio group: arrow keys move the choice, and the group is one tab stop.
 */
function SegmentsInner<V extends string | boolean>(
  { value, options, onCommit, highlightClassName, segmentClassName, hoverClassName, className, onKeyDown, onPointerMove, onPointerLeave, ...props }: SegmentsProps<V>,
  ref: React.ForwardedRef<HTMLDivElement>,
) {
  const field = useInspectorField();
  const group = useRef<HTMLDivElement | null>(null);
  // The chosen segment already has its knob, so the hover box skips it.
  const hover = useSharedHover((item) => item.hasAttribute("data-selected"), field.animated, hoverClassName);
  if (field.unavailable) return <InspectorFieldValue />;

  const icons = options.some((option) => option.icon);
  const mixed = field.mixed || value === null;
  const index = mixed ? -1 : options.findIndex((option) => option.value === value);
  const blocked = !field.editable || field.pending;
  const off = field.disabled || field.locked;
  const choose = (next: V) => {
    if (blocked || field.disabled) return;
    if (mixed || next !== value) onCommit(next);
  };

  return (
    <Tooltip.Provider delay={400}>
      <div
        ref={mergeRefs(ref, group)}
        role="radiogroup"
        id={field.controlId}
        aria-labelledby={field.labelId}
        aria-describedby={field.describedBy}
        aria-readonly={blocked || undefined}
        aria-disabled={off || undefined}
        data-disabled={off || undefined}
        data-icons={icons || undefined}
        data-slot="segments"
        className={cn(
          // A boxed track, the same as Color Picker's format switch: a border and muted fill, with the choice raised on it.
          "relative isolate grid h-[calc(var(--uicoolkit-field-height,2.5rem)-0.5rem)] shrink-0 grid-flow-col auto-cols-fr rounded-md border border-input bg-muted p-0.5 text-sm data-[disabled]:opacity-50 dark:bg-input/40",
          // Icons share the column; text keeps Off/On's compact size at the row's end.
          // Beside other controls (InspectorFieldControls) they take only the width left over.
          icons ? "w-full min-w-0 flex-1" : "w-28 justify-self-end",
          // The row's box already frames it, so only the chosen segment is drawn.
          field.inside && "border-transparent bg-transparent dark:bg-transparent",
          className,
        )}
        onKeyDown={(event: KeyboardEvent<HTMLDivElement>) => {
          onKeyDown?.(event);
          const step = event.key === "ArrowRight" || event.key === "ArrowDown" ? 1 : event.key === "ArrowLeft" || event.key === "ArrowUp" ? -1 : 0;
          if (event.defaultPrevented || !step) return;
          event.preventDefault();
          const next = Math.min(options.length - 1, Math.max(0, (index < 0 ? 0 : index) + step));
          choose(options[next].value);
          group.current?.querySelectorAll<HTMLButtonElement>('[role="radio"]')[next]?.focus();
        }}
        onPointerMove={(event) => {
          onPointerMove?.(event);
          hover.handlers.onPointerMove(event);
        }}
        // Entering an item shows the box at once, before the pointer moves again.
        onPointerOver={hover.handlers.onPointerMove}
        onPointerLeave={(event) => {
          onPointerLeave?.(event);
          hover.handlers.onPointerLeave();
        }}
        {...props}
      >
        {hover.highlight}
        {index >= 0 && (
          <span
            aria-hidden
            className={cn(
              // A thin border keeps the chosen segment visible on the track in light themes, where the two are close.
              "absolute inset-y-0.5 left-0.5 -z-10 rounded-sm bg-background shadow-sm ring-1 ring-border",
              // Without the track behind it, the chosen segment takes the primary tint used for selections.
              field.inside && "bg-primary/10",
              field.animated && "transition-transform duration-200 ease-out motion-reduce:transition-none",
              highlightClassName,
            )}
            style={{ width: `calc((100% - 0.25rem) / ${options.length})`, transform: `translateX(${index * 100}%)` }}
          />
        )}
        {options.map((option, position) => {
          const selected = position === index;
          const segment = (
            <button
              key={String(option.value)}
              type="button"
              role="radio"
              aria-checked={selected}
              aria-label={option.icon ? option.label : undefined}
              // One tab stop: the chosen segment, or the first when mixed.
              tabIndex={selected || (index < 0 && position === 0) ? 0 : -1}
              disabled={off}
              data-selected={selected || undefined}
              className={cn(
                "inline-flex min-w-0 items-center justify-center gap-1 rounded-sm text-muted-foreground outline-none transition-colors duration-150 select-none motion-reduce:transition-none [&_svg]:size-4",
                "focus-visible:bg-foreground/10 focus-visible:text-foreground data-selected:text-foreground",
                // The shared hover box sits behind it; the segment only brightens.
                "not-data-selected:enabled:hover:text-foreground",
                segmentClassName,
              )}
              onClick={() => choose(option.value)}
            >
              {option.icon ?? option.label}
              {/* Takes the segment's own text colour so it reads on any selected fill. */}
              {selected && <InspectorFieldLock aria-hidden className="size-3.5 text-current opacity-70" />}
            </button>
          );
          return option.icon && !off ? (
            <Tip key={String(option.value)} label={option.label}>
              {segment}
            </Tip>
          ) : (
            segment
          );
        })}
      </div>
    </Tooltip.Provider>
  );
}

export const InspectorFieldSegments = forwardRef(SegmentsInner) as <V extends string | boolean>(
  props: SegmentsProps<V> & { ref?: React.Ref<HTMLDivElement> },
) => ReactElement | null;

type ToggleButtonProps = Omit<ComponentPropsWithoutRef<"button">, "children" | "onChange"> & {
  /** Whether it is on, or null when a selection differs. The application owns it. */
  pressed: boolean | null;
  /** Names the button and fills its tooltip, such as "Wrap". */
  label: string;
  icon: ReactNode;
  /** Called with the new state; a Mixed button turns on. */
  onCommit: (pressed: boolean) => void;
};

/**
 * A built-in on/off button with an icon, such as Wrap or Flip horizontal. It can be a row's whole
 * control, or sit beside another control inside InspectorFieldControls.
 */
export const InspectorFieldToggleButton = forwardRef<HTMLButtonElement, ToggleButtonProps>(function InspectorFieldToggleButton(
  { pressed, label, icon, onCommit, className, onClick, ...props },
  ref,
) {
  const field = useInspectorField();
  const mixed = field.mixed || pressed === null;
  const blocked = !field.editable || field.pending;
  const off = field.disabled || field.locked;
  const button = (
    <button
      ref={ref}
      type="button"
      aria-label={label}
      aria-pressed={mixed ? "mixed" : !!pressed}
      aria-describedby={field.describedBy}
      disabled={off || field.unavailable}
      data-slot="toggle-button"
      className={cn(
        // Off looks like Boolean's track; on looks like its chosen side, a raised knob with a thin border.
        "grid size-8 shrink-0 place-items-center justify-self-end rounded-md bg-muted text-muted-foreground outline-none transition-[color,background-color,box-shadow] duration-150 [&_svg]:size-4 motion-reduce:transition-none",
        "hover:text-foreground focus-visible:bg-foreground/10 focus-visible:text-foreground disabled:opacity-50",
        // The same soft hover box as segments and actions, inset like a segment in its track; on, the knob is enough.
        "relative before:pointer-events-none before:absolute before:inset-0.5 before:rounded-sm before:bg-foreground/10 before:opacity-0 before:transition-opacity before:duration-150 motion-reduce:before:transition-none",
        "not-aria-pressed:enabled:hover:before:opacity-100",
        "aria-pressed:bg-background aria-pressed:text-foreground aria-pressed:shadow-sm aria-pressed:ring-1 aria-pressed:ring-border",
        // Mixed: a selection holds both, so the knob is outlined but not raised.
        "aria-[pressed=mixed]:outline-1 aria-[pressed=mixed]:-outline-offset-1 aria-[pressed=mixed]:outline-dashed aria-[pressed=mixed]:outline-border",
        // The row's box already frames it, so only the on state is drawn, in the primary tint Boolean uses there.
        field.inside && "bg-transparent aria-pressed:bg-primary/10 aria-pressed:shadow-none aria-pressed:ring-0",
        className,
      )}
      onClick={(event) => {
        onClick?.(event);
        if (event.defaultPrevented || blocked || off) return;
        onCommit(mixed ? true : !pressed);
      }}
      {...props}
    >
      {icon}
    </button>
  );
  return off ? button : (
    <Tooltip.Provider delay={400}>
      <Tip label={label}>{button}</Tip>
    </Tooltip.Provider>
  );
});

/**
 * Puts several controls in the control column side by side, such as Direction segments with a Wrap
 * button, or two flip buttons. Segments with icons take the remaining width.
 */
export const InspectorFieldControls = forwardRef<HTMLDivElement, ComponentPropsWithoutRef<"div">>(function InspectorFieldControls({ className, ...props }, ref) {
  const field = useInspectorField();
  return (
    <div
      ref={ref}
      data-slot="controls"
      className={cn("flex h-[var(--uicoolkit-field-height,2.5rem)] min-w-0 items-center justify-end gap-1.5", field.inside ? "pr-1 pl-2" : "", className)}
      {...props}
    />
  );
});

type ActionsProps = ComponentPropsWithoutRef<"div"> & {
  /** Names the group for assistive technology. Defaults to the row's label. */
  label?: string;
  /** Class for the hover box that slides between actions. */
  hoverClassName?: string;
};

/**
 * A joined group of one-shot action buttons, such as Rotate 90° and the flips. Nothing stays pressed:
 * each press reports one action. It is a toolbar, so Tab reaches it once and arrow keys move between buttons.
 */
export const InspectorFieldActions = forwardRef<HTMLDivElement, ActionsProps>(function InspectorFieldActions({ label, hoverClassName, className, onKeyDown, onPointerMove, onPointerLeave, children, ...props }, ref) {
  const field = useInspectorField();
  const group = useRef<HTMLDivElement | null>(null);
  const hover = useSharedHover(() => false, field.animated, hoverClassName);
  // One tab stop: keep it on an enabled button, the first one until arrow keys move it.
  useEffect(() => {
    const buttons = [...(group.current?.querySelectorAll<HTMLButtonElement>("button") ?? [])];
    const enabled = buttons.filter((button) => !button.disabled);
    if (enabled.some((button) => button.tabIndex === 0)) return;
    for (const button of buttons) button.tabIndex = button === enabled[0] ? 0 : -1;
  });
  return (
    <Tooltip.Provider delay={400}>
      <div
        ref={mergeRefs(ref, group)}
        role="toolbar"
        aria-label={label ?? field.label}
        aria-describedby={field.describedBy}
        data-slot="actions"
        className={cn(
          "relative isolate flex h-[calc(var(--uicoolkit-field-height,2.5rem)-0.5rem)] w-full min-w-0 items-stretch gap-0.5 rounded-lg bg-muted p-0.5",
          // The row's box already frames it.
          field.inside && "bg-transparent",
          className,
        )}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          const step = event.key === "ArrowRight" ? 1 : event.key === "ArrowLeft" ? -1 : 0;
          if (event.defaultPrevented || !step) return;
          const buttons = [...event.currentTarget.querySelectorAll<HTMLButtonElement>("button:not(:disabled)")];
          const index = buttons.indexOf(document.activeElement as HTMLButtonElement);
          if (index < 0) return;
          event.preventDefault();
          const next = buttons[(index + step + buttons.length) % buttons.length];
          for (const button of buttons) button.tabIndex = button === next ? 0 : -1;
          next.focus();
        }}
        onPointerMove={(event) => {
          onPointerMove?.(event);
          hover.handlers.onPointerMove(event);
        }}
        // Entering an item shows the box at once, before the pointer moves again.
        onPointerOver={hover.handlers.onPointerMove}
        onPointerLeave={(event) => {
          onPointerLeave?.(event);
          hover.handlers.onPointerLeave();
        }}
        {...props}
      >
        {hover.highlight}
        {children}
      </div>
    </Tooltip.Provider>
  );
});

type ActionButtonProps = Omit<ComponentPropsWithoutRef<"button">, "children"> & {
  /** Names the action and fills its tooltip, such as "Flip horizontal". */
  label: string;
  icon: ReactNode;
  /** Called once per press. */
  onAction: () => void;
  /** Shortcut text shown in the tooltip, such as "Shift+H". Your app binds the key. */
  shortcut?: string;
};

/** One action in InspectorFieldActions. It is off while the row is locked, read-only, pending or disabled. */
export const InspectorFieldActionButton = forwardRef<HTMLButtonElement, ActionButtonProps>(function InspectorFieldActionButton(
  { label, icon, onAction, shortcut, className, onClick, disabled, tabIndex, ...props },
  ref,
) {
  const field = useInspectorField();
  const off = !!disabled || !field.editable || field.pending;
  const button = (
    <button
      ref={ref}
      type="button"
      aria-label={label}
      aria-keyshortcuts={shortcut}
      disabled={off}
      // InspectorFieldActions gives one button the tab stop.
      tabIndex={tabIndex ?? -1}
      data-slot="action"
      className={cn(
        // A press pushes the key in (flat, no shadow) rather than shrinking it, so taps stay steady.
        "grid min-w-8 flex-1 place-items-center rounded-md text-muted-foreground outline-none transition-[color,background-color,box-shadow] duration-100 ease-out select-none [&_svg]:size-4 motion-reduce:transition-none",
        // The group's shared hover box sits behind it, the same as segments; a press deepens it.
        "hover:text-foreground active:bg-foreground/10 active:text-foreground active:duration-0 focus-visible:bg-foreground/10 focus-visible:text-foreground disabled:pointer-events-none disabled:opacity-50",
        className,
      )}
      onClick={(event) => {
        onClick?.(event);
        if (!event.defaultPrevented && !off) onAction();
      }}
      {...props}
    >
      {icon}
    </button>
  );
  return off ? button : <Tip label={shortcut ? `${label}  ${shortcut}` : label}>{button}</Tip>;
});

"use client";

import { Combobox } from "@base-ui/react/combobox";
import { Select } from "@base-ui/react/select";
import { type ReactNode, useRef, useState, useSyncExternalStore } from "react";
import { InspectorFieldLock } from "./inspector-field-lock";
import { InspectorFieldValue } from "./inspector-field-parts";
import { box, insideControl, useInspectorField } from "./inspector-field-state";
import { cn } from "@/lib/utils";

const phoneQuery = "(max-width: 639px)";
const subscribe = (notify: () => void) => {
  if (typeof window.matchMedia !== "function") return () => {};
  const media = window.matchMedia(phoneQuery);
  media.addEventListener("change", notify);
  return () => media.removeEventListener("change", notify);
};
/** Phones get a bottom sheet; the server renders the desktop popup, then adapts. */
const usePhone = () =>
  useSyncExternalStore(subscribe, () => typeof window.matchMedia === "function" && window.matchMedia(phoneQuery).matches, () => false);

export type InspectorFieldSelectOption = {
  value: string;
  /** Shown in the field and the list. A searchable select matches typed text against it, so keep it plain text there. */
  label: ReactNode;
  disabled?: boolean;
  /** A heading the option is listed under in a searchable select, such as "Document fonts". */
  group?: string;
};

type SelectProps = {
  /** The committed choice. The application owns it. */
  value: string;
  options: InspectorFieldSelectOption[];
  /** Called when a different option is chosen. */
  onCommit: (value: string) => void;
  className?: string;
  /** Class for the popup (or the bottom sheet on phones). */
  popupClassName?: string;
  /**
   * Class for each option. Highlighted options have data-highlighted; the chosen one data-selected.
   * Its tick has data-slot="check", so a look can mark the choice with colour instead.
   */
  itemClassName?: string;
  /** Where the popup is portalled. Defaults to document.body. */
  container?: HTMLElement | null;
  positionMethod?: "absolute" | "fixed";
  /**
   * A search field at the top of the list that filters the options as you type, for long lists such
   * as fonts. Options with a group are listed under its heading.
   */
  searchable?: boolean;
  /** Draws an option in the list and the field, such as a font in its own face. Defaults to its label. */
  renderOption?: (option: InspectorFieldSelectOption) => ReactNode;
};

/**
 * Draws each font family option in its own face. Pass as renderOption with font family values. A
 * family that isn't installed falls back to the system sans-serif rather than the browser's serif.
 */
export const inspectorFieldFontOption = (option: InspectorFieldSelectOption) => <span style={{ fontFamily: `"${option.value}", system-ui, sans-serif` }}>{option.label}</span>;

const chevron = (
  <svg aria-hidden viewBox="0 0 10 6" className="h-1.5 w-2.5" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
    <path d="M1.5 1.25 5 4.75l3.5-3.5" />
  </svg>
);
const check = (
  <svg aria-hidden viewBox="0 0 16 16" className="size-3.5" fill="none" stroke="currentColor" strokeWidth={1.75} strokeLinecap="round" strokeLinejoin="round">
    <path d="m3.5 8.5 3 3 6-7" />
  </svg>
);
const sheetStyle = { position: "fixed", top: "auto", bottom: 0, left: 0, right: 0, width: "100%", transform: "none" } as const;
const popupClass = (phone: boolean, animated: boolean) =>
  cn(
    "max-h-[var(--available-height)] min-w-[var(--anchor-width)] overflow-y-auto rounded-md border border-border bg-popover p-1 text-popover-foreground shadow-md outline-none",
    phone && "max-h-[80dvh] w-full rounded-t-2xl rounded-b-none p-4 pb-[max(1rem,env(safe-area-inset-bottom))]",
    animated &&
      (phone
        ? "transition-[transform,opacity] duration-200 ease-out data-[ending-style]:translate-y-full data-[starting-style]:translate-y-full motion-reduce:transition-none"
        : "origin-[var(--transform-origin)] transition-[transform,opacity] duration-150 ease-out data-[ending-style]:scale-95 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[starting-style]:opacity-0 motion-reduce:transition-none"),
  );
const itemClass = (phone: boolean) =>
  cn(
    "flex min-h-8 cursor-pointer items-center justify-between gap-3 rounded-sm px-2 text-sm outline-none select-none data-[disabled]:opacity-50 data-[highlighted]:bg-accent data-[highlighted]:text-accent-foreground",
    phone && "min-h-11",
  );

/**
 * A built-in select for the second column: a field-sized trigger and a themed list of options.
 * Keyboard and typeahead come from Base UI; on phones the list opens as a bottom sheet.
 */
export function InspectorFieldSelect(props: SelectProps) {
  const field = useInspectorField();
  if (field.unavailable) return <InspectorFieldValue />;
  return props.searchable ? <SearchSelect {...props} /> : <PlainSelect {...props} />;
}

/** With the label inside, the menu opens under the whole row rather than under the value alone. */
function useRowAnchor(trigger: { current: HTMLButtonElement | null }) {
  const field = useInspectorField();
  return field.inside
    ? () => {
        const row = field.rootRef.current;
        const button = trigger.current;
        if (!row || !button) return button;
        return {
          contextElement: row,
          getBoundingClientRect: () => {
            const box = row.getBoundingClientRect();
            const own = button.getBoundingClientRect();
            return new DOMRect(box.left, own.top, box.width, own.height);
          },
        };
      }
    : undefined;
}

function PlainSelect({ value, options, onCommit, className, popupClassName, itemClassName, container, positionMethod, renderOption }: SelectProps) {
  const field = useInspectorField();
  const phone = usePhone();
  const trigger = useRef<HTMLButtonElement | null>(null);
  const [open, setOpen] = useState(false);
  const anchor = useRowAnchor(trigger);
  // Read-only, locked, disabled or pending: the value shows, but the menu never opens.
  const blocked = !field.editable || field.pending;
  const items = options.map((option) => ({ value: option.value, label: renderOption ? renderOption(option) : option.label }));

  return (
    <Select.Root
      items={items}
      value={field.mixed ? null : value}
      onValueChange={(next) => {
        if (next !== null && (field.mixed || next !== value)) onCommit(next as string);
      }}
      disabled={field.disabled || field.locked}
      readOnly={blocked}
      open={open && !blocked}
      onOpenChange={(next) => setOpen(next && !blocked)}
    >
      <Select.Trigger
        ref={trigger}
        id={field.controlId}
        aria-describedby={field.describedBy}
        className={cn(
          box,
          "flex items-center gap-2 px-3 data-[popup-open]:border-ring data-[readonly]:cursor-default group-data-pending/inspector:animate-pulse",
          field.inside && insideControl,
          className,
        )}
      >
        <Select.Value className={cn("min-w-0 flex-1 truncate data-[placeholder]:text-muted-foreground", field.align === "start" ? "text-start" : "text-end")} placeholder={field.messages.mixed} />
        <InspectorFieldLock />
        {field.editable && (
          <Select.Icon className="shrink-0 text-muted-foreground">
            <svg aria-hidden viewBox="0 0 10 6" className="h-1.5 w-2.5" fill="none" stroke="currentColor" strokeWidth={1.5} strokeLinecap="round" strokeLinejoin="round">
              <path d="M1.5 1.25 5 4.75l3.5-3.5" />
            </svg>
          </Select.Icon>
        )}
      </Select.Trigger>
      <Select.Portal container={container ?? undefined}>
        {phone && <Select.Backdrop className="fixed inset-0 z-50 bg-black/40" />}
        <Select.Positioner
          anchor={anchor}
          alignItemWithTrigger={false}
          sideOffset={4}
          positionMethod={positionMethod}
          className="z-50 outline-none"
          style={phone ? { position: "fixed", top: "auto", bottom: 0, left: 0, right: 0, width: "100%", transform: "none" } : undefined}
        >
          <Select.Popup
            className={cn(
              "max-h-[var(--available-height)] min-w-[var(--anchor-width)] overflow-y-auto rounded-md border border-border bg-popover p-1 text-popover-foreground shadow-md outline-none",
              phone && "max-h-[80dvh] w-full rounded-t-2xl rounded-b-none p-4 pb-[max(1rem,env(safe-area-inset-bottom))]",
              field.animated &&
                (phone
                  ? "transition-[transform,opacity] duration-200 ease-out data-[ending-style]:translate-y-full data-[starting-style]:translate-y-full motion-reduce:transition-none"
                  : "origin-[var(--transform-origin)] transition-[transform,opacity] duration-150 ease-out data-[ending-style]:scale-95 data-[ending-style]:opacity-0 data-[starting-style]:scale-95 data-[starting-style]:opacity-0 motion-reduce:transition-none"),
              popupClassName,
            )}
          >
            <Select.List>
              {options.map((option) => (
                <Select.Item
                  key={option.value}
                  value={option.value}
                  disabled={option.disabled}
                  className={cn(
                    "flex min-h-8 cursor-pointer items-center justify-between gap-3 rounded-sm px-2 text-sm outline-none select-none data-[disabled]:opacity-50 data-[highlighted]:bg-accent data-[highlighted]:text-accent-foreground",
                    phone && "min-h-11",
                    itemClassName,
                  )}
                >
                  <Select.ItemText>{renderOption ? renderOption(option) : option.label}</Select.ItemText>
                  <Select.ItemIndicator data-slot="check">
                    <svg aria-hidden viewBox="0 0 16 16" className="size-3.5" fill="none" stroke="currentColor" strokeWidth={1.75} strokeLinecap="round" strokeLinejoin="round">
                      <path d="m3.5 8.5 3 3 6-7" />
                    </svg>
                  </Select.ItemIndicator>
                </Select.Item>
              ))}
            </Select.List>
          </Select.Popup>
        </Select.Positioner>
      </Select.Portal>
    </Select.Root>
  );
}

type Group = { value: string; items: InspectorFieldSelectOption[] };
const plainLabel = (option: InspectorFieldSelectOption) => (typeof option.label === "string" ? option.label : option.value);

/**
 * The searchable select: the field opens a list with a search field at its top that filters as you
 * type, with options under their group headings. Keyboard comes from Base UI's Combobox; on phones
 * the list opens as a bottom sheet.
 */
function SearchSelect({ value, options, onCommit, className, popupClassName, itemClassName, container, positionMethod, renderOption }: SelectProps) {
  const field = useInspectorField();
  const phone = usePhone();
  const trigger = useRef<HTMLButtonElement | null>(null);
  const [open, setOpen] = useState(false);
  const search = useRef<HTMLInputElement | null>(null);
  const anchor = useRowAnchor(trigger);
  const blocked = !field.editable || field.pending;
  const draw = (option: InspectorFieldSelectOption) => (renderOption ? renderOption(option) : option.label);
  const selected = field.mixed ? null : (options.find((option) => option.value === value) ?? null);
  const grouped = options.some((option) => option.group);
  const groups: Group[] = [];
  for (const option of options) {
    const name = option.group ?? "";
    const group = groups.find((item) => item.value === name) ?? groups[groups.push({ value: name, items: [] }) - 1];
    group.items.push(option);
  }
  const item = (option: InspectorFieldSelectOption) => (
    <Combobox.Item key={option.value} value={option} disabled={option.disabled} className={cn(itemClass(phone), itemClassName)}>
      <span className="min-w-0 truncate">{draw(option)}</span>
      <Combobox.ItemIndicator data-slot="check">{check}</Combobox.ItemIndicator>
    </Combobox.Item>
  );

  return (
    <Combobox.Root<InspectorFieldSelectOption>
      items={grouped ? (groups as never) : options}
      value={selected}
      itemToStringLabel={plainLabel}
      isItemEqualToValue={(a, b) => a.value === b.value}
      // The first match is highlighted as you type, so Enter picks it.
      autoHighlight
      onValueChange={(next) => {
        if (next && (field.mixed || next.value !== value)) onCommit(next.value);
      }}
      disabled={field.disabled || field.locked}
      readOnly={blocked}
      open={open && !blocked}
      onOpenChange={(next) => setOpen(next && !blocked)}
    >
      <Combobox.Trigger
        ref={trigger}
        id={field.controlId}
        aria-describedby={field.describedBy}
        className={cn(
          box,
          "flex items-center gap-2 px-3 data-[popup-open]:border-ring data-[readonly]:cursor-default group-data-pending/inspector:animate-pulse",
          field.inside && insideControl,
          className,
        )}
      >
        <span className={cn("min-w-0 flex-1 truncate", field.align === "start" ? "text-start" : "text-end", !selected && "text-muted-foreground")}>
          {selected ? draw(selected) : field.messages.mixed}
        </span>
        <InspectorFieldLock />
        {field.editable && <Combobox.Icon className="shrink-0 text-muted-foreground">{chevron}</Combobox.Icon>}
      </Combobox.Trigger>
      <Combobox.Portal container={container ?? undefined}>
        {phone && <Combobox.Backdrop className="fixed inset-0 z-50 bg-black/40" />}
        <Combobox.Positioner anchor={anchor} align="start" sideOffset={4} positionMethod={positionMethod} className="z-50 outline-none" style={phone ? sheetStyle : undefined}>
          <Combobox.Popup
            // Typing searches at once on desktop; on phones the sheet takes focus, so the keyboard waits for a tap.
            initialFocus={phone ? true : search}
            className={cn(popupClass(phone, field.animated), "flex max-h-[min(24rem,var(--available-height))] flex-col overflow-hidden p-0", phone && "max-h-[80dvh] p-0", popupClassName)}>
            <div className="border-b border-border p-1">
              <Combobox.Input
                ref={search}
                placeholder={field.messages.search}
                aria-label={field.messages.search}
                className="h-8 w-full rounded-sm bg-transparent px-2 text-sm outline-none placeholder:text-muted-foreground"
              />
            </div>
            <Combobox.Empty>
              <div className="px-3 py-4 text-sm text-muted-foreground">{field.messages.noResults}</div>
            </Combobox.Empty>
            <Combobox.List className="min-h-0 flex-1 overflow-y-auto overscroll-contain p-1 empty:hidden">
              {grouped
                ? (group: Group) => (
                    <Combobox.Group key={group.value} items={group.items} className="pb-1 last:pb-0">
                      {group.value && <Combobox.GroupLabel className="px-2 pt-1.5 pb-1 text-xs text-muted-foreground select-none">{group.value}</Combobox.GroupLabel>}
                      <Combobox.Collection>{(option: InspectorFieldSelectOption) => item(option)}</Combobox.Collection>
                    </Combobox.Group>
                  )
                : (option: InspectorFieldSelectOption) => item(option)}
            </Combobox.List>
          </Combobox.Popup>
        </Combobox.Positioner>
      </Combobox.Portal>
    </Combobox.Root>
  );
}

"use client";

import { type ComponentPropsWithoutRef, type MutableRefObject, type Ref, createContext, useContext } from "react";

/** Replaceable text for the field's states and the built-in toggle. */
export type InspectorFieldMessages = {
  mixed: string;
  unavailable: string;
  locked: string;
  off: string;
  on: string;
  /** The search field's placeholder in a searchable select. */
  search: string;
  /** Shown in a searchable select when nothing matches. */
  noResults: string;
};

export const defaultMessages: InspectorFieldMessages = {
  mixed: "Mixed",
  unavailable: "Not available",
  locked: "Locked",
  off: "Off",
  on: "On",
  search: "Search",
  noResults: "Nothing matches.",
};

/** The shared box for built-in controls, matching Number Field's 40px field. */
export const box =
  "h-[var(--uicoolkit-field-height,2.5rem)] w-full min-w-0 rounded-md border border-[color:var(--uicoolkit-field-border,var(--input))] bg-[var(--uicoolkit-field-bg,transparent)] text-sm shadow-[var(--uicoolkit-field-shadow,0_1px_2px_0_rgb(0_0_0/0.05))] outline-none focus-visible:border-ring disabled:opacity-50 data-[disabled]:opacity-50";

export type InspectorFieldProps = ComponentPropsWithoutRef<"div"> & {
  /** Name of the property, such as "Width". Labels the control. */
  label: string;
  /** The selection holds different values; the control shows a "Mixed" placeholder. */
  mixed?: boolean;
  /** Shown but not editable here. */
  readOnly?: boolean;
  /** Controlled by something else: the control is disabled and a lock shows beside the label. Explain why with `reason`. */
  locked?: boolean;
  /** Does not apply to the selection; shows a dash. Explain why with `reason`. */
  unavailable?: boolean;
  /** Why the property is locked or unavailable. Shown in a tooltip while the row is hovered, and read with the field. */
  reason?: string;
  disabled?: boolean;
  /** A change is being applied; the control waits. */
  pending?: boolean;
  /** Short guidance shown below the field when there is no reason or error to show. */
  hint?: string;
  /** Entrance transitions for messages. Reduced motion is always honored. */
  motion?: boolean;
  /** Where values sit inside built-in controls: "end" (right, the default) or "start" (left). */
  align?: InspectorFieldAlign;
  /**
   * "outside" (the default) puts the label in its own column beside the control's box.
   * "inside" draws one box around the whole row, with the label at its start, as many design tools do.
   */
  labelPosition?: InspectorFieldLabelPosition;
  /** Class for the tooltip that shows why the property is locked or unavailable. */
  tooltipClassName?: string;
  messages?: Partial<InspectorFieldMessages>;
};

export type InspectorFieldAlign = "start" | "end";
export type InspectorFieldLabelPosition = "outside" | "inside";

/** Built-in controls drop their own box when the row draws one around the label and control. */
export const insideControl =
  "pr-3.5 border-transparent bg-transparent shadow-none focus-visible:border-transparent focus-visible:ring-0 aria-invalid:border-transparent aria-invalid:ring-0 hover:bg-transparent data-[popup-open]:border-transparent";

export type InspectorFieldContextValue = {
  label: string;
  mixed: boolean;
  readOnly: boolean;
  locked: boolean;
  unavailable: boolean;
  disabled: boolean;
  pending: boolean;
  /** Not read-only, locked, unavailable or disabled. */
  editable: boolean;
  reason?: string;
  hint?: string;
  animated: boolean;
  messages: InspectorFieldMessages;
  align: InspectorFieldAlign;
  /** The row draws the box, with the label inside it. */
  inside: boolean;
  /** A rejected value's message from a built-in control, or null. */
  error: string | null;
  setError: (error: string | null) => void;
  /** The id of the message below the field, or undefined while there is none. */
  describedBy: string | undefined;
  labelId: string;
  controlId: string;
  messageId: string;
  rootRef: MutableRefObject<HTMLDivElement | null>;
};

export const InspectorFieldContext = createContext<InspectorFieldContextValue | null>(null);

/** State of the nearest InspectorField, for building custom parts or wiring another control. */
export function useInspectorField() {
  const context = useContext(InspectorFieldContext);
  if (!context) throw new Error("InspectorField parts must be rendered inside <InspectorField>.");
  return context;
}

export function mergeRefs<T>(...refs: (Ref<T> | undefined)[]) {
  return (node: T | null) => {
    for (const ref of refs) {
      if (typeof ref === "function") ref(node);
      else if (ref) (ref as MutableRefObject<T | null>).current = node;
    }
  };
}

"use client";

import { type ComponentPropsWithoutRef, forwardRef, useRef, useState } from "react";
import { InspectorFieldLock } from "./inspector-field-lock";
import { InspectorFieldValue } from "./inspector-field-parts";
import { box, insideControl, useInspectorField } from "./inspector-field-state";
import { cn } from "@/lib/utils";

/** "boxed" is a field like Number Field's; "ghost" reads as plain text until hovered or focused. */
export type InspectorFieldTextVariant = "boxed" | "ghost";

type TextProps = Omit<ComponentPropsWithoutRef<"input">, "value" | "defaultValue" | "onChange"> & {
  variant?: InspectorFieldTextVariant;
  /** The committed text. The application owns it. */
  value: string;
  /** Called once per finished edit, with text that changed and passed `validate`. */
  onCommit: (value: string) => void;
  /** Return a message to reject the text; it stays in the field for fixing. */
  validate?: (value: string) => string | null | undefined;
};

/**
 * A built-in text control for the second column. Enter or leaving the field commits,
 * Escape reverts. With a mixed selection it starts empty and typing applies to every item.
 */
export const InspectorFieldText = forwardRef<HTMLInputElement, TextProps>(function InspectorFieldText(
  { value, onCommit, validate, variant = "boxed", className, placeholder, onKeyDown, onBlur, onFocus, ...props },
  ref,
) {
  const field = useInspectorField();
  const [draft, setDraftState] = useState<string | null>(null);
  // Mirrors the draft so the blur that follows Enter or Escape cannot commit it again.
  const draftRef = useRef<string | null>(null);
  const setDraft = (next: string | null) => {
    draftRef.current = next;
    setDraftState(next);
  };

  if (field.unavailable) return <InspectorFieldValue />;

  const revert = () => {
    setDraft(null);
    field.setError(null);
  };

  const submit = () => {
    const text = draftRef.current;
    if (text === null) return;
    if (!field.mixed && text === value) return revert();
    const message = validate?.(text);
    if (message) return field.setError(message);
    revert();
    onCommit(text);
  };

  return (
    <div className="relative min-w-0">
      <InspectorFieldLock className="pointer-events-none absolute top-1/2 right-3 -translate-y-1/2" />
      <input
        ref={ref}
        id={field.controlId}
        type="text"
        autoComplete="off"
        aria-describedby={field.describedBy}
        aria-invalid={field.error ? true : undefined}
        disabled={field.disabled || field.locked}
        readOnly={!field.editable || field.pending}
        placeholder={field.mixed ? field.messages.mixed : placeholder}
        data-variant={variant}
        data-locked={field.locked || undefined}
        className={cn(
          box,
          "px-3 placeholder:text-muted-foreground data-locked:pr-9 group-data-pending/inspector:animate-pulse aria-invalid:border-destructive aria-invalid:ring-destructive/20",
          field.align === "start" ? "text-start" : "text-end",
          variant === "ghost" && "border-transparent shadow-none hover:bg-accent/60 focus-visible:bg-transparent read-only:hover:bg-transparent",
          field.inside && insideControl,
          className,
        )}
        {...props}
        value={draft ?? (field.mixed ? "" : value)}
        onFocus={(event) => {
          onFocus?.(event);
          event.currentTarget.select();
        }}
        onChange={(event) => {
          setDraft(event.target.value);
          if (field.error) field.setError(null);
        }}
        onKeyDown={(event) => {
          onKeyDown?.(event);
          if (event.defaultPrevented) return;
          if (event.key === "Enter" && !event.nativeEvent.isComposing && event.keyCode !== 229) {
            event.preventDefault();
            submit();
          } else if (event.key === "Escape" && draftRef.current !== null) {
            // Stop here so an enclosing sheet or popover stays open.
            event.preventDefault();
            event.stopPropagation();
            revert();
          }
        }}
        onBlur={(event) => {
          onBlur?.(event);
          submit();
        }}
      />
    </div>
  );
});

